import UIKit

enum ArtStudioDirectPages {
    private static let pages: [String] = [
        "",
        "",
        ""
    ]

    static var count: Int { pages.count }

    static func image(at rawIndex: Int) -> UIImage {
        let index = min(max(rawIndex, 0), pages.count - 1)
        guard let data = Data(base64Encoded: pages[index]),
              let image = UIImage(data: data)?.withRenderingMode(.alwaysOriginal) else {
            return fallback
        }
        return image
    }

    private static var fallback: UIImage {
        let renderer = UIGraphicsImageRenderer(size: CGSize(width: 240, height: 176))
        return renderer.image { ctx in
            UIColor.white.setFill()
            ctx.fill(CGRect(x: 0, y: 0, width: 240, height: 176))
        }
    }
}
